def test_assistant_with_code_block(parser_provider):
    payload = json.loads(
        r"""
    {
      "agent": {
        "template": {
          "format": {
            "kind": "jinja2"
          },
          "parser": {
            "kind": "prompty"
          }
        }
      },
      "rendered": "assistant:\nHere is code:\n```python\nprint('hello')\n```\n\nuser:\nThanks"
    }
        """,
        strict=False,
    )
    agent = Agent.load(payload["agent"])
    rendered = payload["rendered"]
    context = payload.get("context")
    kind = agent.template.parser.kind
    impl = resolve_parser(kind, parser_provider)
    assert impl is not None, f"assistant_with_code_block: no Parser attached for {kind}"
    result = impl.parse(agent, rendered, context)
    if inspect.isawaitable(result):
        result = asyncio.run(result)
    assert result is not None


